arguments.new_string:
        if self.default is not RAISE:
            args.append('default=%r' % self.default)
        return '%s(%s)' % (cn, ', '.join(args))


class Auto(object):
    """The ``Auto`` specifier type enables glom to automatically determine
    how to process data based on its type. When Auto is used as a spec,
    glom will introspect the target data and apply appropriate transformations.

    This is particularly useful for handling polymorphic data structures
    where different types need different processing logic.

    Args:
       default_spec: A fallback spec to use when auto-detection doesn't match
         any registered handler. Defaults to T (pass-through).

    >>> target = {'items': [1, 2, 3]}
    >>> glom(target, Auto())  # passes through based on introspection
    {'items': [1, 2, 3]}

    """
    def __init__(self, default_spec=None):
        self.default_spec = default_spec if default_spec is not None else T

    def glomit(self, target, scope):
        return scope[glom](target, self.default_spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default_spec is T:
            return '%s()' % cn
        return '%s(%r)' % (cn, self.default_spec)


class Fill(object):
    """The ``Fill`` specifier type fills in missing values with defaults.
    When accessing data that may be missing, Fill ensures a value is always
    returned by using the provided default.

    This is similar to Coalesce but more focused on filling in gaps in
    nested structures rather than trying multiple paths.

    Args:
       spec: The spec to evaluate. If it fails or returns a skipped value,
         the default will be used.
       default: The value to use when the spec fails or produces a skipped value.

    >>> target = {'a': 'value'}
    >>> glom(target, Fill('b', 'fallback'))
    'fallback'
    >>> glom(target, Fill('a', 'fallback'))
    'value'

    """
    def __init__(self, spec, default):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            result = scope[glom](target, self.spec, scope)
            if result is SKIP or result is OMIT:
                return self.default
            return result
        except GlomError:
            return self.default

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.spec, self.default)


class Iter(object):
    """The ``Iter`` specifier type iterates over an iterable target,
    applying a subspec to each element.

    This is useful for transforming sequences of items, such as applying
    a transformation to each element in a list.

    Args:
       spec: A subspec to apply to each element in the iterable.

    >>> target = [1, 2, 3]
    >>> glom(target, Iter(Call(int, 'upper') if isinstance(0, str) else lambda x: x * 2))
    [2, 4, 6]

    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        iterator = iterate(target)
        result = []
        for item in iterator:
            val = scope[glom](item, self.spec, scope)
            if val is not SKIP:
                result.append(val)
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Let(object):
    """The ``Let`` specifier type allows binding names to intermediate
    values within a spec, enabling variable capture and reuse.

    This is useful for complex specs where you want to extract and reuse
    intermediate results without repeating computations.

    Args:
       bindings: A dict mapping names to their corresponding specs.
       spec: The main spec to evaluate, which can reference bound names
         via T['name'] or S['name'].

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'sum': ('a', 'b')}, T['sum']))
    Traceback (most recent call last):
    ...
    PathAccessError: could not access 'sum', part 0 of Path('sum'), got error: KeyError('sum',) ...

    In practice, you'd typically combine with T to access the bound name:
    >>> from glom import T
    >>> glom(target, Let({'a_val': 'a'}, T['a_val']))
    1

    """
    def __init__(self, bindings, spec):
        self.bindings = bindings
        self.spec = spec

    def glomit(self, target, scope):
        new_scope = dict(scope)
        for name, sub_spec in self.bindings.items():
            new_scope[name] = scope[glom](target, sub_spec, scope)
        return scope[glom](target, self.spec, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        bindings_str = ', '.join('%s=%r' % (k, v) for k, v in self.bindings.items())
        return '%s({%s}, %r)' % (cn, bindings_str, self.spec)


