class Invoke(object):
    """The ``Invoke`` specifier type calls a function/method with arguments
    extracted from the target data.

    This is useful for invoking operations on extracted data, such as
    calling methods on objects or applying functions to extracted values.

    Args:
       func: A callable to invoke. Can be a string path (for attribute access),
         a Spec, or a direct callable.
       *args: Positional arguments to pass to the function.
       **kwargs: Keyword arguments to pass to the function.

    >>> target = {'name': 'hello'}
    >>> glom(target, Invoke(str.upper, 'name'))
    'HELLO'

    """
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        # Evaluate func if it's a spec
        if isinstance(self.func, (Spec, TType)):
            func = scope[glom](target, self.func, scope)
        elif isinstance(self.func, basestring):
            func = scope[glom](target, self.func, scope)
        else:
            func = self.func

        # Evaluate args
        eval_args = []
        for arg in self.args:
            if isinstance(arg, (Spec, TType)):
                eval_args.append(scope[glom](target, arg, scope))
            elif isinstance(arg, basestring):
                eval_args.append(scope[glom](target, arg, scope))
            else:
                eval_args.append(arg)

        # Evaluate kwargs
        eval_kwargs = {}
        for k, v in self.kwargs.items():
            if isinstance(v, (Spec, TType)):
                eval_kwargs[k] = scope[glom](target, v, scope)
            elif isinstance(v, basestring):
                eval_kwargs[k] = scope[glom](target, v, scope)
            else:
                eval_kwargs[k] = v

        return func(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        args = [repr(self.func)] + [repr(a) for a in self.args]
        kwargs_str = ', '.join('%s=%r' % (k, v) for k, v in self.kwargs.items())
        if kwargs_str:
            args.append(kwargs_str)
        return '%s(%s)' % (cn, ', '.join(args))


